// J2 instruction decoder types.
//
// Ported from reference/soc_top/components/cpu/decode/decode_pkg.vhd (which
// was generated by decode/gen). Field order of every struct and literal order
// of every enum matches the VHDL so flattened bit vectors compare 1:1 with the
// GHDL-converted reference. Literals are type-prefixed (see j2_cpu_pkg).
package j2_decode_pkg;
  import j2_cpu_pkg::*;

  typedef enum logic [1:0] {ALUX_XBUS, ALUX_FC, ALUX_ROTCL, ALUX_ZERO} aluinx_sel_t;
  typedef enum logic [1:0] {ALUY_YBUS, ALUY_IMM, ALUY_R0} aluiny_sel_t;
  typedef enum logic [1:0] {DEC_SIMPLE, DEC_REVERSE, DEC_MICROCODE} cpu_decode_type_t;
  typedef enum logic [0:0] {NORMAL_INSTR, SYSTEM_INSTR} instruction_plane_t;
  typedef enum logic [2:0] {
    MACB_NOT_BUSY, MACB_EX_NOT_STALL, MACB_WB_NOT_STALL, MACB_EX_BUSY, MACB_WB_BUSY
  } mac_busy_t;
  typedef enum logic [1:0] {MACIN1_XBUS, MACIN1_ZBUS, MACIN1_WBUS} macin1_sel_t;
  typedef enum logic [1:0] {MACIN2_YBUS, MACIN2_ZBUS, MACIN2_WBUS} macin2_sel_t;
  typedef enum logic [1:0] {MADDR_XBUS, MADDR_YBUS, MADDR_ZBUS} mem_addr_sel_t;
  typedef enum logic [0:0] {MWDATA_ZBUS, MWDATA_YBUS} mem_wdata_sel_t;
  typedef enum logic [1:0] {REGSEL_R0, REGSEL_R15, REGSEL_RA, REGSEL_RB} reg_sel_t;
  typedef enum logic [2:0] {
    SR_PREV, SR_WBUS, SR_ZBUS, SR_DIV0U, SR_ARITH, SR_LOGIC, SR_INT_MASK, SR_SET_T
  } sr_sel_t;
  typedef enum logic [1:0] {T_CLEAR, T_SET, T_SHIFT, T_CARRY} t_sel_t;
  typedef enum logic [1:0] {XBUS_IMM, XBUS_REG, XBUS_PC} xbus_sel_t;
  typedef enum logic [2:0] {
    YBUS_IMM, YBUS_REG, YBUS_MACH, YBUS_MACL, YBUS_PC, YBUS_SR
  } ybus_sel_t;
  typedef enum logic [2:0] {
    ZBUS_ARITH, ZBUS_LOGIC, ZBUS_SHIFT, ZBUS_MANIP, ZBUS_YBUS, ZBUS_WBUS
  } zbus_sel_t;

  // System-plane synthetic op commands: code = 0000 0 cmd[2:0] vec[7:0]
  localparam logic [2:0] SYS_INTERRUPT       = 3'd0;
  localparam logic [2:0] SYS_ERROR           = 3'd1;
  localparam logic [2:0] SYS_BREAK           = 3'd2;
  localparam logic [2:0] SYS_RESET_CPU       = 3'd3;
  localparam logic [2:0] SYS_SLOT_ILLEGAL    = 3'd6;
  localparam logic [2:0] SYS_GENERAL_ILLEGAL = 3'd7;

  typedef struct packed {
    instruction_plane_t plane;
    logic [15:0]        code;
    logic [7:0]         addr;
  } operation_t;

  // ------------------------------------------------- decoder output records
  typedef struct packed {
    alumanip_t   manip;
    aluinx_sel_t inx_sel;
    aluiny_sel_t iny_sel;
  } alu_ctrl_t;

  typedef struct packed {
    arith_func_t    func;
    logic           ci_en;
    arith_sr_func_t sr;
  } arith_ctrl_t;

  typedef struct packed {
    xbus_sel_t   x_sel;
    ybus_sel_t   y_sel;
    zbus_sel_t   z_sel;
    logic [31:0] imm_val;
  } buses_ctrl_t;

  typedef struct packed {
    alu_ctrl_t      alu;
    shiftfunc_t     shift;
    arith_ctrl_t    arith;
    logic_func_t    logic_func;
    logic_sr_func_t logic_sr;
  } func_ctrl_t;

  typedef struct packed {
    logic issue;
    logic addr_sel;
  } instr_ctrl_t;

  typedef struct packed {
    logic        com1;
    logic        wrmach;
    logic        wrmacl;
    logic        s_latch;
    macin1_sel_t sel1;
    macin2_sel_t sel2;
    mult_state_t com2;
  } mac_ctrl_t;

  typedef struct packed {
    logic           issue;
    logic           wr;
    logic           lock;
    mem_size_t      size;
    mem_addr_sel_t  addr_sel;
    mem_wdata_sel_t wdata_sel;
  } mem_ctrl_t;

  typedef struct packed {
    logic wr_z;
    logic wrpr;
    logic inc;
  } pc_ctrl_t;

  typedef struct packed {
    regnum_t num_x;
    regnum_t num_y;
    regnum_t num_z;
    regnum_t num_w;
    logic    wr_z;
    logic    wr_w;
  } reg_ctrl_t;

  typedef struct packed {
    sr_sel_t    sel;
    t_sel_t     t;
    logic [3:0] ilevel;
  } sr_ctrl_t;

  // ------------------------------------------------------ pipeline records
  typedef struct packed {
    logic           wrpc_z;
    logic           wrsr_z;
    logic           ma_issue;
    logic           wrpr_pc;
    zbus_sel_t      zbus_sel;
    sr_sel_t        sr_sel;
    t_sel_t         t_sel;
    mem_addr_sel_t  mem_addr_sel;
    mem_wdata_sel_t mem_wdata_sel;
    logic           wrreg_z;
    logic           wrmach;
    logic           wrmacl;
    shiftfunc_t     shiftfunc;
    logic           mulcom1;
    mult_state_t    mulcom2;
    macin1_sel_t    macsel1;
    macin2_sel_t    macsel2;
  } pipeline_ex_stall_t;

  typedef struct packed {
    logic [31:0]    imm_val;
    xbus_sel_t      xbus_sel;
    ybus_sel_t      ybus_sel;
    regnum_t        regnum_z;
    regnum_t        regnum_x;
    regnum_t        regnum_y;
    alumanip_t      alumanip;
    aluinx_sel_t    aluinx_sel;
    aluiny_sel_t    aluiny_sel;
    arith_func_t    arith_func;
    logic           arith_ci_en;
    arith_sr_func_t arith_sr_func;
    logic_func_t    logic_func;
    logic_sr_func_t logic_sr_func;
    logic           mac_busy;
    logic           ma_wr;
    logic           mem_lock;
    mem_size_t      mem_size;
  } pipeline_ex_t;

  typedef struct packed {
    logic incpc;
    logic if_issue;
    logic ifadsel;
  } pipeline_id_t;

  typedef struct packed {
    logic        mulcom1;
    logic        wrmach;
    logic        wrmacl;
    logic        wrreg_w;
    logic        wrsr_w;
    macin1_sel_t macsel1;
    macin2_sel_t macsel2;
    mult_state_t mulcom2;
  } pipeline_wb_stall_t;

  typedef struct packed {
    regnum_t regnum_w;
    logic    mac_busy;
  } pipeline_wb_t;

  typedef struct packed {
    pipeline_ex_t       ex1;
    pipeline_ex_stall_t ex1_stall;
    pipeline_wb_t       wb1;
    pipeline_wb_t       wb2;
    pipeline_wb_t       wb3;
    pipeline_wb_stall_t wb1_stall;
    pipeline_wb_stall_t wb2_stall;
    pipeline_wb_stall_t wb3_stall;
  } pipeline_t;

  // Default (all-zero-equivalent) values used for bubbles and reset. These
  // are exactly the "zero outputs by default" assignments of decode_table.
  localparam pipeline_ex_stall_t STAGE_EX_STALL_RESET = '{
    wrpc_z: 1'b0, wrsr_z: 1'b0, ma_issue: 1'b0, wrpr_pc: 1'b0,
    zbus_sel: ZBUS_ARITH, sr_sel: SR_PREV, t_sel: T_CLEAR,
    mem_addr_sel: MADDR_XBUS, mem_wdata_sel: MWDATA_ZBUS,
    wrreg_z: 1'b0, wrmach: 1'b0, wrmacl: 1'b0, shiftfunc: SHIFT_LOGIC,
    mulcom1: 1'b0, mulcom2: MULT_NOP, macsel1: MACIN1_XBUS, macsel2: MACIN2_YBUS};

  localparam pipeline_ex_t STAGE_EX_RESET = '{
    imm_val: 32'h0, xbus_sel: XBUS_IMM, ybus_sel: YBUS_IMM,
    regnum_z: 5'd0, regnum_x: 5'd0, regnum_y: 5'd0,
    alumanip: MANIP_SWAP_BYTE, aluinx_sel: ALUX_XBUS, aluiny_sel: ALUY_YBUS,
    arith_func: ARITH_ADD, arith_ci_en: 1'b0, arith_sr_func: ASR_ZERO,
    logic_func: LOGIC_NOT, logic_sr_func: LSR_ZERO,
    mac_busy: 1'b0, ma_wr: 1'b0, mem_lock: 1'b0, mem_size: SZ_BYTE};

  localparam pipeline_wb_stall_t STAGE_WB_STALL_RESET = '{
    mulcom1: 1'b0, wrmach: 1'b0, wrmacl: 1'b0, wrreg_w: 1'b0, wrsr_w: 1'b0,
    macsel1: MACIN1_XBUS, macsel2: MACIN2_YBUS, mulcom2: MULT_NOP};

  localparam pipeline_wb_t STAGE_WB_RESET = '{regnum_w: 5'd0, mac_busy: 1'b0};

  localparam pipeline_id_t STAGE_ID_RESET = '{incpc: 1'b0, if_issue: 1'b0, ifadsel: 1'b0};

  localparam pipeline_t PIPELINE_RESET = '{
    ex1: STAGE_EX_RESET, ex1_stall: STAGE_EX_STALL_RESET,
    wb1: STAGE_WB_RESET, wb2: STAGE_WB_RESET, wb3: STAGE_WB_RESET,
    wb1_stall: STAGE_WB_STALL_RESET, wb2_stall: STAGE_WB_STALL_RESET,
    wb3_stall: STAGE_WB_STALL_RESET};

  // All combinational outputs of the decode table for one (op, t_bcc).
  // Bundled so tests can compare the whole table output as one vector.
  typedef struct packed {
    logic               debug;
    logic               delay_jump;
    logic               dispatch;
    logic               event_ack_0;
    pipeline_ex_t       ex;
    pipeline_ex_stall_t ex_stall;
    pipeline_id_t       id;
    logic               ilevel_cap;
    logic               mac_s_latch;
    logic               mac_stall_sense;
    logic               maskint_next;
    logic               slp;
    pipeline_wb_t       wb;
    pipeline_wb_stall_t wb_stall;
  } decode_table_o_t;

  // ---------------------------------------- instruction pre-decode checks
  // Ported from decode_body.vhd (generated by the original decode/gen).

  // Instructions that write PC (illegal in a delay slot): RTE, RTS, JMP, JSR,
  // BRAF, BSRF, BF, BF/S, BT, BT/S, BRA, BSR, TRAPA.
  function automatic logic check_illegal_delay_slot(logic [15:0] code);
    return (code[15:12] == 4'b0000 && code[3:2] == 2'b00 && code[0]) ||
           (code[15:14] == 2'b10 && code[12:11] == 2'b01 && code[8]) ||
           (code[15:13] == 3'b101) ||
           (code[15] && code[13:8] == 6'b000011) ||
           (!code[15] && code[13:12] == 2'b00 && code[4:0] == 5'b01011);
  endfunction

  // Only 0xFFxx is treated as illegal (as in the original).
  function automatic logic check_illegal_instruction(logic [15:0] code);
    return code[15:8] == 8'hff;
  endfunction

endpackage
